            version: self.version.clone(),
        }
    }
}

// 서버 초기화
pub fn initialize_sovereign_server(port: i32) -> SovereignServer {
    let http_response = create_http_server(port);
    let http_server = HttpServer {
        port: port,
        is_running: true,
        request_count: 0i32,
        error_count: 0i32,
    };

    SovereignServer {
