    let tenant1 = create_tenant("Demo Tenant 1".to_string(), "key_123456".to_string());
    let tenant2 = create_tenant("Demo Tenant 2".to_string(), "key_789012".to_string());

    let manager1 = add_tenant(server.tenant_manager, tenant1);
    let manager2 = add_tenant(manager1, tenant2);

    SovereignServer {
        http_server: server.http_server,
        tenant_manager: manager2,
        metrics_store: server.metrics_store,
        is_initialized: server.is_initialized,
        version: server.version,
    }
}

// 인증 처리
pub fn authenticate_request(server: SovereignServer, api_key: String) -> (bool, String) {
    let tenant_id = find_tenant_by_key(server.tenant_manager, api_key);
    if tenant_id == "" {
        (false, "unauthorized".to_string())
    } else {
        (true, tenant_id)
    }
}

