            if i > 0i32 {
                body.push_str(",");
            }
            let tenant = server.tenant_manager.tenants[(i as usize)].clone();
            body.push_str(tenant_to_json(tenant).as_str());
            i = i + 1i32;
        }
        body.push_str("],\"total\":");
        body.push_str(server.tenant_manager.tenant_count.to_string().as_str());
        body.push_str("}");

