            status_code: 200i32,
            status_text: "OK".to_string(),
            headers: vec!["Content-Type: application/json".to_string()],
            body: body,
        };
        (response, server)
    } else {
        let mut body = String::new();
        body.push_str("{\"error\":\"not_found\",\"path\":\"");
        body.push_str(req.path.as_str());
        body.push_str("\"}");
        let response = HttpResponse {
            status_code: 404i32,
            status_text: "Not Found".to_string(),
            headers: vec!["Content-Type: application/json".to_string()],
            body: body,
        };
        (response, server)
    }
}

// 상태 리포트
pub fn get_server_status(server: SovereignServer) -> String {
    let mut status = String::new();
    status.push_str("{\"version\":\"");
    status.push_str(server.version.as_str());
    status.push_str("\",\"port\":");
    status.push_str(server.http_server.port.to_string().as_str());
    status.push_str(",\"running\":");
    status.push_str(if server.http_server.is_running { "true" } else { "false" });
    status.push_str(",\"tenants\":");
    status.push_str(server.tenant_manager.tenant_count.to_string().as_str());
    status.push_str(",\"total_executions\":");
    status.push_str(server.metrics_store.total_executions.to_string().as_str());
    status.push_str(",\"success_rate\":");
    status.push_str(get_success_rate(server.metrics_store.clone()).to_string().as_str());
    status.push_str("%}");
    status
}

