// Phase 12 테스트: HTTP 서버 + 멀티테넌트 + 메트릭

use crate::phase12::http_server::*;
use crate::phase12::tenant_manager::*;
use crate::phase12::metrics_store::*;
use crate::phase12::server_integration::*;

// ===== HTTP 서버 테스트 (4개) =====

pub fn test_http_server_creation() -> bool {
    let response = create_http_server(8080i32);
    response.status_code == 200i32 && response.body.contains("server_initialized")
}

pub fn test_health_check() -> bool {
    let response = handle_health_check();
    response.status_code == 200i32 && response.body.contains("healthy")
}

pub fn test_metrics_endpoint() -> bool {
    let response = handle_metrics();
    response.status_code == 200i32 && response.body.contains("requests")
}

pub fn test_request_routing() -> bool {
    let req = HttpRequest {
        method: "GET".to_string(),
        path: "/invalid".to_string(),
        headers: vec![],
        body: "".to_string(),
    };
    let response = handle_request(req);
    response.status_code == 404i32
}

// ===== 멀티테넌트 테스트 (5개) =====

pub fn test_create_tenant() -> bool {
    let tenant = create_tenant("Test Tenant".to_string(), "key_test".to_string());
    tenant.name == "Test Tenant" && tenant.status == "active"
}

pub fn test_tenant_manager_creation() -> bool {
    let manager = create_tenant_manager();
    manager.tenant_count == 0i32 && manager.active_count == 0i32
}

pub fn test_add_tenant() -> bool {
    let manager = create_tenant_manager();
    let tenant = create_tenant("T1".to_string(), "k1".to_string());
    let new_manager = add_tenant(manager, tenant);
    new_manager.tenant_count == 1i32
}

pub fn test_find_tenant_by_key() -> bool {
    let manager = create_tenant_manager();
    let tenant = create_tenant("T1".to_string(), "key_123".to_string());
    let new_manager = add_tenant(manager, tenant);
    let found_id = find_tenant_by_key(new_manager, "key_123".to_string());
    found_id != ""
}

pub fn test_check_quota() -> bool {
    let tenant = create_tenant("T1".to_string(), "k1".to_string());
    check_quota(tenant) == true
}

// ===== 메트릭 저장소 테스트 (5개) =====

pub fn test_metrics_store_creation() -> bool {
    let store = create_metrics_store();
    store.total_executions == 0i32
}

pub fn test_save_execution_record() -> bool {
    let store = create_metrics_store();
    let record = ExecutionRecord {
        record_id: "rec_1".to_string(),
        tenant_id: "t_1".to_string(),
        code: "fn test() { 1 }".to_string(),
