// Sovereign Workspace v1.0.0 - FV-Lang 순수 구현
// Phase 12: 완전 FV-Lang 기반 HTTP 서버

mod lib;

use lib::phase12::server_integration::*;

fn main() {
    println!("╔════════════════════════════════════════════════════╗");
    println!("║  🚀 Sovereign Workspace v1.0.0 - FV-Lang Edition  ║");
    println!("╚════════════════════════════════════════════════════╝");
    println!();

    // 서버 초기화
    println!("🔧 서버 초기화 중... (포트 8080)");
    let server = initialize_sovereign_server(8080i32);

    // 데모 테넌트 추가
    println!("👥 데모 테넌트 추가 중...");
    let server = add_demo_tenants(server);

    // 서버 상태 출력
    println!();
    println!("📊 서버 상태:");
    println!("{}", get_server_status(server.clone()));

    println!();
    println!("✅ 서버 준비 완료!");
    println!("📝 엔드포인트:");
    println!("  - GET  /health              헬스 체크");
    println!("  - GET  /metrics             메트릭 조회");
    println!("  - GET  /admin/tenants       테넌트 관리");
    println!();
    println!("🔑 API 키 (테스트용):");
    println!("  - Demo Tenant 1: key_123456");
    println!("  - Demo Tenant 2: key_789012");
    println!();
    println!("💡 사용 예시:");
    println!("  curl -H 'X-API-Key: key_123456' http://localhost:8080/health");
    println!();
}

